# ✅ 2. **precision()** – controls decimal places

```cpp
#include <iostream>
using namespace std;

int main() {
    double x = 3.141592;

    cout << "Default: " << x << endl;

    cout.precision(3);  // total digits = 3
    cout << "Precision(3): " << x << endl;

    cout << fixed;      // now precision means digits *after decimal*
    cout.precision(3);
    cout << "Fixed + Precision(3): " << x << endl;

    return 0;
}
```

**Output:**

```
Default: 3.14159
Precision(3): 3.14
Fixed + Precision(3): 3.142
```

---

# ✅ 3. **fill()** – sets filling character for blank space

```cpp
#include <iostream>
using namespace std;

int main() {
    cout.fill('*');     // fill blank spaces with *

    cout.width(10);     // total width = 10
    cout << 123 << endl;

    return 0;
}
```

**Output:**

```
*******123
```

---

# ✅ 4. **setf()** – sets formatting flags

Example: show decimal point always

```cpp
#include <iostream>
using namespace std;

int main() {
    cout.setf(ios::showpoint);  // always show decimal point
    cout.setf(ios::fixed);      // fixed format

    double x = 25.0;

    cout << x << endl;

    return 0;
}
```

**Output:**

```
25.000000
```

---

# ✅ 5. **unsetf()** – remove formatting flag

```cpp
#include <iostream>
using namespace std;

int main() {
    cout.setf(ios::hex, ios::basefield);  // set hex mode
    cout << 255 << endl;                  // prints ff

    cout.unsetf(ios::hex);                // remove hex
    cout << 255 << endl;                  // prints 255

    return 0;
}
```

**Output:**

```
ff
255
```

